H.background();
const v = H.plot2d({ xMin: 0, xMax: 1, yMin: -2.6, yMax: 2.6 });
v.grid(); v.axes();
const n = Math.max(1, Math.round(P.n));       // harmonic number (loops)
const A = Math.max(0.05, P.A);                 // amplitude of each travelling wave (cm)
const L = 1;                                   // string length normalized to 1 (label in m via P.L)
const Lm = Math.max(0.2, P.L);                 // physical string length (m)
const k = n * Math.PI / L;                     // wave number for fixed-fixed string
const env = 2 * A;                             // standing-wave envelope amplitude
// temporal factor cos(omega t): bounded oscillation
const ph = Math.cos(t * 2.2);
// the standing wave y(x) = 2A sin(kx) cos(wt)
v.fn(x => env * Math.sin(k * x) * ph, { color: H.colors.accent, width: 3 });
// faint envelope (the +/- 2A sin(kx) bound the string never exceeds)
v.fn(x => env * Math.sin(k * x), { color: H.colors.sub, width: 1.2 });
v.fn(x => -env * Math.sin(k * x), { color: H.colors.sub, width: 1.2 });
// fixed ends (the string is clamped) + nodes (sin(kx)=0) and antinodes
for (let i = 0; i <= n; i++) {
  const xn = i / n;                            // node positions: x = i*lambda/2 = i*L/n
  v.dot(xn, 0, { r: 5, fill: H.colors.warn });
}
for (let i = 0; i < n; i++) {
  const xa = (i + 0.5) / n;                    // antinode positions (max swing)
  v.dot(xa, env * Math.sin(k * xa) * ph, { r: 5, fill: H.colors.good });
}
const lam = 2 * Lm / n;                         // wavelength = 2L/n
H.text("Standing wave: y = 2A sin(kx) cos(wt)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("harmonic n = " + n + "   wavelength = 2L/n = " + lam.toFixed(2) + " m   nodes = " + (n + 1), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "string", color: H.colors.accent }, { label: "node", color: H.colors.warn }, { label: "antinode", color: H.colors.good }], H.W - 170, 28);
